import { EventEmitter } from 'node:events';
import { createRequire } from 'node:module';
import path from 'node:path';

const require = createRequire(import.meta.url);

let fsevents;
function loadFsevents() {
  if (fsevents) return fsevents;
  if (process.platform !== 'darwin') {
    throw new Error(`FSEvents is only available on macOS (current platform: ${process.platform})`);
  }
  fsevents = require('fsevents');
  return fsevents;
}

/**
 * Watches a directory tree using native macOS FSEvents.
 *
 * Emits:
 *   'change' ({ path, event, type, flags, id, changes }) for every filesystem event
 *   'error'  (err) if the native watcher fails to start
 */
export class Watcher extends EventEmitter {
  #root;
  #since;
  #stop = null;

  /**
   * @param {string} root      Directory to watch (recursively).
   * @param {object} [options]
   * @param {number} [options.since]  FSEvents event ID to replay history from.
   */
  constructor(root, { since } = {}) {
    super();
    this.#root = path.resolve(root);
    this.#since = since;
  }

  get root() {
    return this.#root;
  }

  get running() {
    return this.#stop !== null;
  }

  start() {
    if (this.#stop) return this;
    const fse = loadFsevents();
    const handler = (file, flags, id) => {
      const info = fse.getInfo(file, flags);
      this.emit('change', { ...info, flags, id });
    };
    this.#stop = this.#since === undefined
      ? fse.watch(this.#root, handler)
      : fse.watch(this.#root, this.#since, handler);
    return this;
  }

  async stop() {
    if (!this.#stop) return;
    const stop = this.#stop;
    this.#stop = null;
    await stop();
  }
}

export function watch(root, onChange, options) {
  const watcher = new Watcher(root, options);
  if (onChange) watcher.on('change', onChange);
  return watcher.start();
}
EOF
cat > bin/mac-fswatch.js <<'EOF'
#!/usr/bin/env node
import { parseArgs } from 'node:util';
import { Watcher } from '../src/index.js';

const { values, positionals } = parseArgs({
  allowPositionals: true,
  options: {
    json: { type: 'boolean', default: false },
    help: { type: 'boolean', short: 'h', default: false },
  },
});

if (values.help) {
  console.log('Usage: mac-fswatch [--json] [path]\n\nWatches path (default: cwd) recursively via FSEvents.');
  process.exit(0);
}

const watcher = new Watcher(positionals[0] ?? process.cwd());

watcher.on('change', (e) => {
  if (values.json) {
    console.log(JSON.stringify(e));
  } else {
    console.log(`${e.event.padEnd(12)} ${e.type.padEnd(9)} ${e.path}`);
  }
});

try {
  watcher.start();
} catch (err) {
  console.error(`mac-fswatch: ${err.message}`);
  process.exit(1);
}

console.error(`Watching ${watcher.root} (Ctrl-C to stop)`);

const shutdown = async () => {
  await watcher.stop();
  process.exit(0);
};
process.on('SIGINT', shutdown);
process.on('SIGTERM', shutdown);
EOF
