import { test } from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import { Watcher } from '../src/index.js';

const isMac = process.platform === 'darwin';

test('throws a clear error on non-macOS platforms', { skip: isMac }, () => {
  assert.throws(() => new Watcher('.').start(), /only available on macOS/);
});

test('reports file creation', { skip: !isMac, timeout: 10_000 }, async () => {
  // realpath: FSEvents reports /private/var/... rather than the /var symlink
  const dir = await fs.realpath(await fs.mkdtemp(path.join(os.tmpdir(), 'mac-fswatch-')));
  const target = path.join(dir, 'hello.txt');
  const watcher = new Watcher(dir).start();
  try {
    const seen = new Promise((resolve) => {
      watcher.on('change', (e) => {
        if (e.path === target && e.event === 'created') resolve(e);
      });
    });
    // Give FSEvents a moment to register the stream before writing.
    await new Promise((r) => setTimeout(r, 200));
    await fs.writeFile(target, 'hi');
    const event = await seen;
    assert.equal(event.type, 'file');
  } finally {
    await watcher.stop();
    await fs.rm(dir, { recursive: true, force: true });
  }
});
EOF
cat > README.md <<'EOF'
# mac-fswatch

macOS file-watching tool built on native [FSEvents](https://developer.apple.com/documentation/coreservices/file_system_events)
via the [`fsevents`](https://github.com/fsevents/fsevents) N-API binding. macOS only.

## Usage

```sh
npm install
npm start -- ~/some/dir          # human-readable output
npm start -- --json ~/some/dir   # one JSON object per event
```

As a library:

```js
import { watch } from 'mac-fswatch';

const watcher = watch('/path/to/dir', (e) => {
  // e: { path, event, type, flags, id, changes: { inode, finder, access, xattrs } }
  console.log(e.event, e.path);
});

await watcher.stop();
```

Pass `{ since: <eventId> }` to replay events from FSEvents history starting at a previous event ID.

## Tests

```sh
npm test
```

The event tests only run on macOS; on other platforms they are skipped.
